class Player:
    _MODES = ("off", "all", "one")

    def __init__(self, songs, repeat="off"):
        self._songs = list(songs)
        self._check(repeat)
        self._repeat = repeat
        self._index = 0

    @classmethod
    def _check(cls, mode):
        if mode not in cls._MODES:
            raise ValueError("Bad repeat mode")

    @property
    def repeat(self):
        return self._repeat

    @repeat.setter
    def repeat(self, mode):
        self._check(mode)
        self._repeat = mode

    @property
    def current(self):
        if 0 <= self._index < len(self._songs):
            return self._songs[self._index]
        return None

    def next(self):
        if not self._songs or self._index >= len(self._songs):
            return None
        if self._repeat == "one":
            return self.current
        self._index += 1
        if self._index >= len(self._songs) and self._repeat == "all":
            self._index = 0
        return self.current

    def previous(self):
        if not self._songs:
            return None
        if self._index >= len(self._songs):
            self._index = len(self._songs) - 1
        elif self._index > 0:
            self._index -= 1
        elif self._repeat == "all":
            self._index = len(self._songs) - 1
        return self.current

    def enqueue(self, song):
        self._songs.append(song)

    def play_next(self, song):
        if self._index >= len(self._songs):
            self._songs.append(song)
        else:
            self._songs.insert(self._index + 1, song)

    def __iter__(self):
        return iter(self._songs[self._index:])
